"use strict";var TextBox=function(n){var t={initialize:function(){t.initEvent()},initEvent:function(){n("#btnMarketingSearch").on("click",function(){var i=t.getSearchParam(),n;t.getTextList(i);n=t.getLinkGenerationParam();t.getTextLink(n)});n("#dataContainerList").on("change","#DeviceType",function(){var n=t.getSearchParam();t.getTextList(n)});n("#btnGenerateLink").on("click",function(){var n=t.getLinkGenerationParam();t.getTextLink(n)})},getSearchParam:function(){return{category:n("#Category").val(),language:n("#Language").val(),currency:n("#Currency").val(),deviceType:n("#DeviceType").val(),selectedDomainId:n("#Domain").val(),selectedPage:n("#MemberSitePage").val()}},getTextList:function(t){n.ajax({type:"GET",dataType:"html",cache:!1,data:t,url:Site.resolveRelativeUrl("UserPanel/GetText"),success:function(t){n("#marketingDataList").html(t)}})},getLinkGenerationParam:function(){return{selectedLanguage:n("#Language").val(),selectedDomainId:n("#Domain").val(),selectedPage:n("#MemberSitePage").val()}},getTextLink:function(t){n.ajax({type:"GET",dataType:"html",cache:!1,data:t,url:Site.resolveRelativeUrl("UserPanel/GenerateLink"),success:function(t){n("#textLinkList").html(t)},beforeSend:function(){Site.showLoader()},complete:function(){Site.hideLoader()}})}};return t}(jQuery);TextBox.initialize();